DROP DATABASE IF EXISTS `lat_spotify`;
CREATE DATABASE `lat_spotify`;
USE `lat_spotify`;

DROP TABLE IF EXISTS `track_stat`;
CREATE TABLE `track_stat` (
  `id` VARCHAR(255),
  `track_name` VARCHAR(255),
  `artist_id` VARCHAR(255),
  `album_id` VARCHAR(255),
  `track_genre_id` VARCHAR(255),
  `popularity` INT,
  `duration_ms` INT,
  `danceability` INT,
  `energy` INT,
  `loudness` INT,
  `speechiness` INT,
  `acousticness` INT,
  `instrumentalness` FLOAT(53),
  `liveness` INT,
  `valence` INT,
  `tempo` INT
);


DROP TABLE IF EXISTS `artists`;
CREATE TABLE `artists` (
  `artist_id` VARCHAR(255),
  `artists` VARCHAR(255)
);


DROP TABLE IF EXISTS `album`;
CREATE TABLE `album` (
  `album_id` VARCHAR(255),
  `album_name` VARCHAR(255),
  `artist_id` VARCHAR(255)
);


DROP TABLE IF EXISTS `track_genre`;
CREATE TABLE `track_genre` (
  `genre_id` VARCHAR(255),
  `genre` VARCHAR(255)
);


